-- Ensina-me: expansão do material e do banco de prática
-- Reproduz a ampliação aplicada em 2026-10-01.
begin;

update public.material_sections
set position = 10, updated_at = now()
where section_type = 'review'
  and position in (6,8)
  and material_id in (
    '00000000-0000-4000-8000-000000010002'::uuid,'ff7dafa5-7776-4b66-a65f-db6c4f583472'::uuid,'7a1ee5b1-49e4-4722-9241-a9cd33464be0'::uuid,'84439dee-5451-47a7-9062-9a7664db631d'::uuid,'00000000-0000-4000-8000-000000010078'::uuid,'0aca8546-f2ad-46ad-a8c7-21707cc46a59'::uuid,'bc46afac-e6d6-49d2-8387-13c40d3d0f0b'::uuid,'00000000-0000-4000-8000-000000010154'::uuid,'43562e58-bff1-4eb3-9dd3-b7ab291362c0'::uuid,'d0aee9ac-e285-477e-aaec-e0a0e6964b18'::uuid,'00000000-0000-4000-8000-000000010230'::uuid,'10c77160-d405-4484-a63c-e29ab1342f87'::uuid
  );

insert into public.material_sections (material_id,title,content,position,section_type)
select v.material_id,v.title,v.content,v.position,v.section_type
from (values
('00000000-0000-4000-8000-000000010002'::uuid,'Conceitos indispensáveis para dominar','Para dominar este tópico, é importante distinguir conceitos que aparecem juntos, mas não são equivalentes. Desenvolvimento envolve transformações do sujeito ao longo do tempo, enquanto aprendizagem diz respeito à apropriação de conhecimentos, habilidades e modos de agir em experiências sociais e educativas. A relação entre os dois pode ser analisada por diferentes perspectivas teóricas.

Na perspectiva construtivista, o estudante participa ativamente da construção e reorganização de seus conhecimentos. Na perspectiva histórico-cultural, o desenvolvimento é analisado em relação à cultura, à linguagem, às interações e às formas de mediação. Em provas, compare sempre os conceitos, o papel do sujeito e o papel das condições educativas antes de escolher uma alternativa.',6,'deepening'),
('00000000-0000-4000-8000-000000010002'::uuid,'Exemplos integrados e como analisar situações educativas','Considere uma criança que resolve sozinha uma tarefa simples, mas precisa de perguntas e pistas para enfrentar uma tarefa mais complexa. O professor não está fazendo a atividade pelo estudante; está criando condições para que ele avance. A situação pode ser analisada perguntando: o que o aluno já consegue fazer? O que consegue fazer com ajuda? Que tipo de mediação está sendo oferecida? O apoio está sendo ajustado?

Em situações de prova ou trabalho, evite explicações monocausais. Uma dificuldade de aprendizagem pode exigir análise do conhecimento prévio, da tarefa, das experiências anteriores, da mediação e do contexto. O ponto central é usar a teoria para interpretar a situação e justificar uma decisão pedagógica.',7,'examples'),
('00000000-0000-4000-8000-000000010002'::uuid,'Conexões entre teorias e conceitos','Ao comparar teorias, organize a análise por perguntas: como o sujeito aprende? qual o papel da experiência? como a interação participa do processo? qual é o lugar da escola? A perspectiva construtivista enfatiza a atividade do sujeito na construção do conhecimento; a perspectiva histórico-cultural enfatiza as relações sociais, a cultura e a mediação. As diferenças não devem ser reduzidas a slogans.

Em questões comparativas, procure primeiro a característica que a alternativa atribui a cada perspectiva. Isso ajuda a evitar confusões como tratar mediação social como se fosse apenas transmissão de conteúdo ou interpretar construção ativa como ausência de ensino.',6,'deepening'),
('00000000-0000-4000-8000-000000010002'::uuid,'Checklist de domínio para prova e trabalho','Você domina este tópico quando consegue: explicar a diferença entre desenvolvimento e aprendizagem; resumir as ideias centrais de Piaget e Vygotsky sem misturá-las; interpretar uma situação escolar usando conceitos de mediação e construção do conhecimento; identificar o papel das condições educativas; e justificar uma intervenção pedagógica com base na teoria.

Para trabalhos, não basta citar o nome de um autor. Explique a ideia, aplique-a à situação e mostre por que ela sustenta sua análise.',8,'review'),
('ff7dafa5-7776-4b66-a65f-db6c4f583472'::uuid,'Conceitos indispensáveis para dominar','Didática não deve ser reduzida a uma coleção de técnicas. Ela envolve pensar a relação entre finalidades educativas, conteúdos, estudantes, professor, estratégias, condições de ensino e formas de acompanhamento da aprendizagem. Uma decisão didática faz sentido quando responde a um objetivo e considera o contexto concreto em que será realizada.

Por isso, duas aulas sobre o mesmo conteúdo podem usar estratégias diferentes sem que uma seja automaticamente melhor que a outra. Em avaliações, procure a alternativa que articula objetivo, conteúdo, estudantes, mediação e evidências de aprendizagem. Desconfie de respostas absolutas que tratam uma técnica como universal ou que separam completamente ensinar de aprender.',6,'deepening'),
('ff7dafa5-7776-4b66-a65f-db6c4f583472'::uuid,'Exemplos integrados e como analisar decisões didáticas','Imagine que uma turma demonstra dificuldade para relacionar um conceito com situações concretas. Uma decisão didática possível é retomar a explicação com exemplos, pedir comparação entre casos e observar novamente o raciocínio dos estudantes. A estratégia muda porque a evidência de aprendizagem mudou a decisão do professor.

Esse tipo de análise aparece em provas e trabalhos quando se pede para justificar uma metodologia. O importante não é nomear a técnica mais sofisticada, mas explicar por que ela é coerente com a aprendizagem pretendida e com as características da turma.',7,'examples'),
('ff7dafa5-7776-4b66-a65f-db6c4f583472'::uuid,'Conexões entre Didática, planejamento e avaliação','Didática, planejamento e avaliação formam um sistema. O planejamento explicita o que se pretende ensinar e como organizar a experiência; a Didática analisa as decisões de ensino e aprendizagem; a avaliação produz evidências que permitem acompanhar e revisar essas decisões. Por isso, uma boa prática não escolhe método, conteúdo e avaliação de forma independente.

Em uma questão, quando uma alternativa apresenta um único elemento como solução universal, verifique se ela ignora objetivo, contexto ou evidências. A coerência costuma estar justamente na relação entre esses elementos.',6,'deepening'),
('ff7dafa5-7776-4b66-a65f-db6c4f583472'::uuid,'Checklist de domínio para prova e trabalho','Você domina este tópico quando consegue: definir Didática sem reduzi-la a técnicas; explicar por que ensinar e aprender são processos relacionados; identificar intencionalidade pedagógica; justificar uma estratégia considerando objetivo e contexto; e explicar como evidências podem levar a ajustes no ensino.

Em trabalhos, use exemplos concretos. Em provas, procure alternativas que articulem finalidade, conteúdo, estudante, mediação e acompanhamento.',8,'review'),
('7a1ee5b1-49e4-4722-9241-a9cd33464be0'::uuid,'Conceitos indispensáveis para dominar','Alfabetização e letramento são dimensões relacionadas da formação do leitor e escritor. Alfabetizar envolve a apropriação do sistema de escrita alfabética; letramento envolve participar de práticas sociais nas quais ler e escrever têm finalidades, gêneros, interlocutores e usos concretos. Trabalhar uma dimensão não exige abandonar a outra.

Para estudar o tema com segurança, saiba explicar a diferença entre aprender como a escrita funciona e aprender a usar a leitura e a escrita em situações sociais. Também é importante reconhecer que práticas significativas não dispensam o ensino sistemático de conhecimentos sobre o sistema de escrita. Em provas, cuidado com alternativas que criam uma oposição rígida entre alfabetizar e letrar.',6,'deepening'),
('7a1ee5b1-49e4-4722-9241-a9cd33464be0'::uuid,'Exemplos integrados e como analisar práticas de alfabetização','Uma atividade pode partir de um convite, lista, história ou outro gênero real, explorar sua finalidade e, dentro da própria situação, observar palavras, letras, relações sonoras e formas de escrita. O sentido social da atividade e a reflexão sistemática sobre o sistema podem coexistir.

Ao analisar uma prática pedagógica, pergunte: qual uso social está presente? O que o estudante precisa aprender sobre o funcionamento da escrita? Que intervenção o professor faz? Que evidência mostrará avanço? Essa leitura integrada é mais útil do que classificar a atividade simplesmente como “alfabetização” ou “letramento”.',7,'examples'),
('7a1ee5b1-49e4-4722-9241-a9cd33464be0'::uuid,'Conexões entre alfabetização, letramento e sistema de escrita','O domínio do tema exige manter três ideias articuladas: aprender o funcionamento do sistema de escrita, aprender a usar a leitura e a escrita socialmente e desenvolver capacidades de produzir sentidos. O ensino pode fazer essas dimensões dialogarem em uma mesma sequência.

Quando a questão apresentar uma prática, identifique quais aprendizagens estão sendo propostas. Uma atividade significativa não deixa de ser sistemática, e o ensino sistemático não precisa abandonar o uso social da linguagem.',6,'deepening'),
('7a1ee5b1-49e4-4722-9241-a9cd33464be0'::uuid,'Checklist de domínio para prova e trabalho','Você domina este tópico quando consegue: diferenciar alfabetização de letramento; explicar por que são articuláveis; analisar uma atividade e identificar sua finalidade social; apontar o conhecimento sobre o sistema de escrita envolvido; e avaliar se a prática oferece oportunidades reais de leitura e escrita.

Em trabalhos, evite oposição rígida entre alfabetizar e letrar. Explique como as duas dimensões podem aparecer de forma integrada e intencional.',8,'review'),
('84439dee-5451-47a7-9062-9a7664db631d'::uuid,'Conceitos indispensáveis para dominar','Planejar é antecipar e organizar decisões, não produzir um roteiro imutável. Um bom planejamento articula objetivos, conteúdos, estratégias, recursos, tempo e avaliação. Os elementos precisam conversar entre si: o objetivo indica a aprendizagem pretendida; os conteúdos oferecem os conhecimentos necessários; os métodos criam oportunidades para aprender; e a avaliação produz evidências sobre o que foi alcançado.

O planejamento também precisa considerar a realidade. Conhecimentos prévios, tempo disponível, composição da turma, recursos e dificuldades observadas influenciam as decisões. Em provas, procure relações de coerência e alinhamento, não listas decoradas. Um planejamento pode ser detalhado e ainda assim ser pedagogicamente frágil se seus elementos estiverem desconectados.',6,'deepening'),
('84439dee-5451-47a7-9062-9a7664db631d'::uuid,'Exemplos integrados e análise de um planejamento','Imagine um plano em que o objetivo é comparar duas concepções, mas todas as atividades pedem apenas definição e a prova cobra memorização. O problema não é apenas a prova: existe uma incoerência entre aquilo que se espera que o estudante faça e as oportunidades oferecidas para desenvolver essa capacidade.

Um planejamento competente também prevê possibilidade de ajuste. Se as evidências mostrarem que um conceito essencial não foi compreendido, o professor pode mudar exemplos, ritmo, agrupamentos, perguntas ou estratégias sem abandonar a finalidade. Em trabalhos acadêmicos, justificar essas escolhas demonstra compreensão do planejamento como processo reflexivo.',7,'examples'),
('84439dee-5451-47a7-9062-9a7664db631d'::uuid,'Conexões entre planejamento, objetivos e avaliação','O planejamento ganha qualidade quando cada decisão pode ser explicada pela aprendizagem que se pretende promover. Objetivos orientam a seleção dos conteúdos e as atividades; as atividades oferecem prática; a avaliação verifica evidências; e essas evidências podem levar ao replanejamento.

Uma boa forma de estudar é pegar um plano e perguntar em sequência: o que deve ser aprendido? o que o estudante precisa fazer para praticar? que evidência mostrará aprendizagem? o que será feito quando a evidência mostrar dificuldade?',6,'deepening'),
('84439dee-5451-47a7-9062-9a7664db631d'::uuid,'Checklist de domínio para prova e trabalho','Você domina este tópico quando consegue: explicar por que planejar não é produzir um roteiro rígido; identificar incoerências entre objetivo, atividade e avaliação; justificar prioridades; reconhecer a importância do contexto; e explicar por que replanejar faz parte do trabalho docente.

Em trabalhos, apresente primeiro a finalidade do planejamento e depois justifique as escolhas. Em provas, procure coerência entre os elementos do plano.',8,'review'),
('00000000-0000-4000-8000-000000010078'::uuid,'Conceitos indispensáveis para dominar','O construtivismo entende o conhecimento como construção do sujeito em interação com objetos de conhecimento e situações. As ideias prévias do estudante importam porque ele interpreta uma experiência nova a partir de esquemas já construídos. Quando uma situação exige reorganização, pode ocorrer desequilíbrio e reconstrução.

Isso não significa que o professor deixe de ensinar. O professor organiza situações, perguntas, problemas e intervenções que favorecem a atividade intelectual do estudante. Em avaliações, diferencie construtivismo de uma pedagogia de abandono: participação ativa do aluno não é ausência de intencionalidade docente.',6,'deepening'),
('00000000-0000-4000-8000-000000010078'::uuid,'Exemplos integrados e análise de situações construtivistas','Uma situação-problema é pedagogicamente produtiva quando cria uma necessidade real de pensar, comparar, testar hipóteses ou reorganizar uma explicação. Depois da tentativa, o professor pode pedir que os estudantes explicitem como raciocinaram e comparem estratégias diferentes.

Ao responder questões, observe se a alternativa preserva a ideia de construção ativa sem eliminar a mediação docente. A escolha mais coerente costuma reconhecer tanto a atividade intelectual do estudante quanto a organização intencional de situações de aprendizagem.',7,'examples'),
('00000000-0000-4000-8000-000000010078'::uuid,'Conexões entre construtivismo e papel docente','Atividade do estudante e intervenção do professor não são opostos. Uma proposta pode favorecer construção ativa ao mesmo tempo em que organiza desafios, oferece perguntas, seleciona materiais, explicita critérios e ajuda a comparar estratégias. O ponto central é que a atividade intelectual do aluno precisa ser considerada no processo de ensino.

Também é importante diferenciar construtivismo de descobrimento sem orientação. Situações de exploração podem fazer parte de uma sequência intencional, com intervenções que ampliem e reorganizem o raciocínio.',6,'deepening'),
('00000000-0000-4000-8000-000000010078'::uuid,'Checklist de domínio para prova e trabalho','Você domina este tópico quando consegue: explicar construção do conhecimento; relacionar esquemas e reorganização; reconhecer situações de desequilíbrio; diferenciar construtivismo de “deixar o aluno sozinho”; e justificar o papel do professor na organização de situações de aprendizagem.

Em provas, desconfie de alternativas absolutas. O construtivismo não implica nem transmissão passiva nem ausência de intervenção.',8,'review'),
('0aca8546-f2ad-46ad-a8c7-21707cc46a59'::uuid,'Conceitos indispensáveis para dominar','O sistema de escrita alfabética não é uma coleção aleatória de letras. Ele organiza relações convencionais entre unidades gráficas e unidades sonoras, além de incluir regularidades e complexidades ortográficas. O estudante precisa construir uma compreensão progressiva desse funcionamento para ler e escrever novas palavras, e não apenas repetir palavras já conhecidas.

O ensino pode combinar reflexão sobre sons, relações entre grafemas e fonemas, comparação de palavras, observação de regularidades e explicitação de convenções. Em provas, diferencie princípio alfabético, conhecimento ortográfico e simples capacidade de copiar uma forma escrita.',6,'deepening'),
('0aca8546-f2ad-46ad-a8c7-21707cc46a59'::uuid,'Exemplos integrados e análise da aprendizagem da escrita','Quando um estudante escreve uma palavra de forma não convencional, a escrita fornece evidências sobre o que ele já compreende. O professor pode comparar a produção com outras palavras, perguntar por que determinada letra foi usada e propor novas situações para observar se o raciocínio se mantém ou muda.

O objetivo não é transformar todo erro em punição, mas usar a produção como dado para decidir o próximo ensino. Essa abordagem ajuda a trabalhar o sistema de escrita de forma progressiva, explícita e reflexiva.',7,'examples'),
('0aca8546-f2ad-46ad-a8c7-21707cc46a59'::uuid,'Conexões entre princípio alfabético, relações grafofonêmicas e ortografia','O princípio alfabético ajuda a compreender que a escrita alfabética estabelece relações sistemáticas entre sons e grafias. A aprendizagem da ortografia acrescenta convenções e regularidades que nem sempre podem ser explicadas por uma relação simples entre um som e uma letra. Por isso, aprender a escrever envolve progressivamente diferentes conhecimentos.

Em uma situação de ensino, compare palavras, observe padrões e explique convenções. Evite tratar toda escrita como memorização isolada e evite também supor que todas as correspondências sejam perfeitamente regulares.',6,'deepening'),
('0aca8546-f2ad-46ad-a8c7-21707cc46a59'::uuid,'Checklist de domínio para prova e trabalho','Você domina este tópico quando consegue: explicar o princípio alfabético; diferenciar grafema e fonema; reconhecer relações entre som e escrita; identificar regularidades ortográficas; justificar ensino explícito; e analisar escritas não convencionais como evidências de aprendizagem.

Em trabalhos, use exemplos de palavras ou situações de escrita para mostrar como o conhecimento do sistema pode ser desenvolvido progressivamente.',8,'review'),
('bc46afac-e6d6-49d2-8387-13c40d3d0f0b'::uuid,'Conceitos indispensáveis para dominar','Consciência fonológica é um conjunto de habilidades de reflexão sobre unidades sonoras da fala. Ela pode envolver palavras, sílabas, rimas, aliterações e, em níveis mais analíticos, fonemas. Consciência fonêmica é uma dimensão mais específica, centrada na identificação e manipulação de fonemas.

Já a relação grafofonêmica articula conhecimentos sobre a escrita com conhecimentos sobre a fala. Os conceitos se relacionam, mas não são sinônimos. Em avaliações, preste atenção ao nível sonoro pedido pela questão e evite exemplos em que apenas uma vogal final é compartilhada para declarar que duas palavras rimam.',6,'deepening'),
('bc46afac-e6d6-49d2-8387-13c40d3d0f0b'::uuid,'Exemplos integrados e análise das relações entre fala e escrita','Uma sequência pode começar com tarefas de percepção sonora mais acessíveis e avançar para segmentar sílabas, identificar sons iniciais ou finais e analisar unidades menores. O desafio deve acompanhar o que os estudantes já conseguem realizar, para que a atividade gere reflexão e não apenas tentativa aleatória.

Na passagem para a escrita, o professor pode relacionar o que foi percebido oralmente com letras e padrões gráficos. A aprendizagem é mais robusta quando o aluno entende o que está comparando e recebe oportunidades de usar esse conhecimento em leitura e escrita.',7,'examples'),
('bc46afac-e6d6-49d2-8387-13c40d3d0f0b'::uuid,'Conexões entre consciência fonológica e alfabetização','Consciência fonológica e aprendizagem da escrita se relacionam, mas uma não deve ser tratada como substituta da outra. Refletir sobre sílabas, rimas, aliterações e fonemas pode apoiar a atenção às unidades sonoras; a aprendizagem do sistema exige também compreender como essas unidades se relacionam com convenções gráficas e com o uso da escrita.

Por isso, atividades orais podem preparar ou apoiar aprendizagens, enquanto atividades de leitura e escrita tornam possível aplicar e ampliar esses conhecimentos.',6,'deepening'),
('bc46afac-e6d6-49d2-8387-13c40d3d0f0b'::uuid,'Checklist de domínio para prova e trabalho','Você domina este tópico quando consegue: definir consciência fonológica; diferenciar rima, aliteração, sílaba e fonema; explicar consciência fonêmica; relacionar reflexão sonora e escrita; e analisar se uma atividade apresenta um nível de dificuldade adequado.

Em provas, observe exatamente qual unidade sonora está sendo manipulada. Em trabalhos, use exemplos precisos e evite classificar como rima situações que não apresentam a relação sonora correspondente.',8,'review'),
('00000000-0000-4000-8000-000000010154'::uuid,'Conceitos indispensáveis para dominar','A perspectiva histórico-cultural compreende o desenvolvimento humano em relação às condições sociais, culturais e históricas. O sujeito não é explicado isoladamente: suas relações, práticas, linguagem e participação em atividades culturalmente organizadas fazem parte da análise.

A mediação é central porque instrumentos e signos, especialmente a linguagem, reorganizam a relação do sujeito com o mundo. Em contexto escolar, isso significa olhar para como o professor, os pares, os materiais e as formas de participação criam oportunidades de aprendizagem e desenvolvimento.',6,'deepening'),
('00000000-0000-4000-8000-000000010154'::uuid,'Exemplos integrados e análise da mediação educativa','Imagine que um estudante consegue resolver um problema depois de ouvir perguntas que orientam sua atenção e organizar seus passos. O apoio do professor funciona como mediação. Com o avanço da aprendizagem, o suporte pode ser reduzido para ampliar a autonomia.

Em uma prova, a alternativa mais coerente costuma considerar o caráter social e mediado da aprendizagem. Evite explicações que tratem o desenvolvimento como processo exclusivamente interno, isolado da cultura, da linguagem e das relações.',7,'examples'),
('00000000-0000-4000-8000-000000010154'::uuid,'Conexões entre mediação, linguagem e desenvolvimento','Na perspectiva histórico-cultural, a aprendizagem é inseparável das formas de participação social e das mediações disponíveis. A linguagem não é apenas veículo de comunicação: ela participa da organização do pensamento e da ação. Instrumentos, signos, professor e pares podem modificar as condições em que o estudante realiza uma atividade.

Ao analisar uma situação educativa, observe quem participa, que recursos mediadores estão presentes, que linguagem é usada e como o apoio está relacionado ao que o estudante já consegue fazer e ao que poderá realizar com ajuda.',6,'deepening'),
('00000000-0000-4000-8000-000000010154'::uuid,'Checklist de domínio para prova e trabalho','Você domina este tópico quando consegue: explicar a perspectiva histórico-cultural; definir mediação; relacionar linguagem e atividade; reconhecer a importância das interações sociais; e interpretar o papel da escola na organização de experiências culturalmente significativas.

Em provas, evite explicações que reduzam desenvolvimento a maturação individual. Em trabalhos, mostre como a situação concreta é mediada social e culturalmente.',8,'review'),
('43562e58-bff1-4eb3-9dd3-b7ab291362c0'::uuid,'Conceitos indispensáveis para dominar','Objetivos, conteúdos e métodos formam um conjunto interdependente. O objetivo define a aprendizagem pretendida; o conteúdo especifica conhecimentos e objetos de estudo relevantes; e os métodos organizam experiências para que o estudante realize as operações necessárias. A avaliação deve produzir evidências compatíveis com essa intenção.

Um objetivo forte é formulado em termos do que o estudante poderá fazer, compreender, analisar, produzir ou justificar. Em trabalhos e provas, não confunda objetivo do professor (“apresentar o conceito”) com objetivo de aprendizagem (“comparar duas concepções usando critérios”). Essa distinção muda a escolha das atividades e das avaliações.',6,'deepening'),
('43562e58-bff1-4eb3-9dd3-b7ab291362c0'::uuid,'Exemplos integrados e análise de escolhas metodológicas','Se o objetivo é analisar uma situação e justificar uma decisão, atividades de comparação de casos, estudo de situação e produção de argumentos tendem a oferecer mais oportunidade para praticar essa capacidade do que uma tarefa limitada à cópia de definições.

Quando o tempo é curto, priorizar conteúdos essenciais é parte da decisão pedagógica. Não se trata de reduzir o rigor, mas de organizar uma sequência realista e coerente, aprofundando aquilo que sustenta as aprendizagens previstas.',7,'examples'),
('43562e58-bff1-4eb3-9dd3-b7ab291362c0'::uuid,'Conexões entre objetivo, conteúdo, método e avaliação','Esses quatro elementos precisam formar uma cadeia coerente. Se o objetivo exige análise, as atividades devem permitir analisar; se exige produção, o estudante precisa produzir; e a avaliação precisa observar essa capacidade. O conteúdo é selecionado não apenas porque “faz parte da matéria”, mas porque oferece conhecimentos necessários para atingir os objetivos.

Essa lógica é útil para estudar qualquer disciplina: leia uma questão e pergunte qual capacidade está sendo cobrada. Depois procure o conteúdo e o tipo de atividade que realmente desenvolvem essa capacidade.',6,'deepening'),
('43562e58-bff1-4eb3-9dd3-b7ab291362c0'::uuid,'Checklist de domínio para prova e trabalho','Você domina este tópico quando consegue: formular objetivos observáveis; justificar a seleção de conteúdos; escolher métodos coerentes; reconhecer desalinhamentos; e explicar por que atividades e avaliações devem corresponder às aprendizagens pretendidas.

Em trabalhos, justifique cada escolha. Em provas, questione alternativas que escolhem metodologia sem indicar finalidade ou contexto.',8,'review'),
('d0aee9ac-e285-477e-aaec-e0a0e6964b18'::uuid,'Conceitos indispensáveis para dominar','Avaliar é produzir e interpretar evidências para tomar decisões educacionais. A função diagnóstica ajuda a compreender condições e conhecimentos iniciais; a formativa acompanha o processo e orienta ajustes; a somativa sintetiza resultados ao final de um período, podendo apoiar registros e certificações.

Uma avaliação de qualidade precisa ter propósito, critérios e evidências coerentes com o objetivo. Uma nota, isoladamente, informa pouco sobre como avançar. O valor pedagógico aumenta quando o estudante entende o que fez, o que precisa melhorar e quais próximos passos pode realizar.',6,'deepening'),
('d0aee9ac-e285-477e-aaec-e0a0e6964b18'::uuid,'Exemplos integrados e uso da avaliação para orientar o ensino','Considere uma turma que consegue repetir uma definição, mas não consegue aplicá-la a um caso. Uma avaliação formativa torna essa diferença visível. O professor pode retomar o conceito, modelar um exemplo, propor nova aplicação e verificar novamente o raciocínio.

Em provas, diferencie “avaliar para classificar” de “avaliar também para orientar a aprendizagem”. O segundo caso depende do uso das evidências. A existência de uma avaliação não a torna automaticamente formativa.',7,'examples'),
('d0aee9ac-e285-477e-aaec-e0a0e6964b18'::uuid,'Conexões entre tipos de avaliação e uso das evidências','Diagnóstica, formativa e somativa são funções diferentes, não apenas nomes de momentos do calendário. Uma avaliação pode ser usada de maneiras distintas conforme a finalidade. O elemento decisivo é o que a evidência busca informar e como ela é utilizada.

Para interpretar uma situação, identifique o propósito: conhecer condições iniciais, acompanhar e ajustar o processo ou sintetizar resultados. Depois observe se os critérios e evidências realmente servem a esse propósito.',6,'deepening'),
('d0aee9ac-e285-477e-aaec-e0a0e6964b18'::uuid,'Checklist de domínio para prova e trabalho','Você domina este tópico quando consegue: diferenciar avaliação diagnóstica, formativa e somativa; explicar critérios e evidências; produzir um exemplo de feedback útil; e justificar um ajuste de ensino a partir de resultados.

Em provas, não associe automaticamente “prova” a somativa ou “atividade” a formativa. Analise a finalidade e o uso da informação.',8,'review'),
('00000000-0000-4000-8000-000000010230'::uuid,'Conceitos indispensáveis para dominar','A dimensão afetiva faz parte da experiência educativa porque expectativas, vínculos, confiança, pertencimento e modos de interação influenciam as condições em que o estudante participa e aprende. Isso não significa que conteúdo e conhecimento percam importância, nem que uma relação acolhedora elimine limites e responsabilidades.

Uma relação pedagógica consistente articula respeito, clareza, escuta, expectativas de aprendizagem e intervenção docente. Em avaliações, desconfie de alternativas que transformam afetividade em permissividade ou que apresentam emoção e cognição como dimensões incompatíveis.',6,'deepening'),
('00000000-0000-4000-8000-000000010230'::uuid,'Exemplos integrados e análise das relações educativas','Em uma correção, o professor pode reconhecer o esforço do estudante, apontar com precisão o que está errado e indicar um caminho de revisão. O feedback mantém a dignidade da pessoa sem abandonar o critério acadêmico.

Essa combinação é importante porque o vínculo educativo não elimina a exigência; ao contrário, pode criar melhores condições para que o estudante enfrente desafios, receba crítica e continue tentando. Em situações de prova, procure relações entre interação, apoio e aprendizagem, e não apenas gestos de simpatia.',7,'examples'),
('00000000-0000-4000-8000-000000010230'::uuid,'Conexões entre afetividade, interação e exigência pedagógica','Afetividade e exigência não precisam ser tratadas como extremos. Relações respeitosas podem coexistir com critérios claros, feedback rigoroso e expectativas elevadas. O vínculo educativo influencia a participação, mas o conteúdo e a intencionalidade pedagógica continuam centrais.

Ao analisar uma situação, procure equilíbrio: o professor acolhe a pessoa, mantém o foco na aprendizagem, explicita o que precisa ser melhorado e oferece caminhos para avançar.',6,'deepening'),
('00000000-0000-4000-8000-000000010230'::uuid,'Checklist de domínio para prova e trabalho','Você domina este tópico quando consegue: explicar o papel da afetividade na relação educativa; relacionar interação e aprendizagem; diferenciar acolhimento de permissividade; reconhecer a importância de limites; e avaliar a qualidade de um feedback.

Em trabalhos, não trate afetividade como simples “carinho”. Relacione-a a condições de participação, expectativas, vínculos e processos de aprendizagem.',8,'review'),
('10c77160-d405-4484-a63c-e29ab1342f87'::uuid,'Conceitos indispensáveis para dominar','Ler envolve construir sentidos, relacionar informações, fazer inferências e mobilizar conhecimentos prévios em função de um texto e de uma situação de uso. A fluência é importante porque reduz esforço para o reconhecimento de palavras, mas não garante compreensão por si só.

Escrever também é participar de práticas sociais com finalidades, gêneros, destinatários e condições de circulação. O ensino pode trabalhar conhecimentos linguísticos de forma explícita dentro de situações significativas, em vez de escolher entre “ensinar a língua” e “usar a língua”. Em provas, observe sempre a finalidade comunicativa e a atividade cognitiva solicitada.',6,'deepening'),
('10c77160-d405-4484-a63c-e29ab1342f87'::uuid,'Exemplos integrados e análise de práticas de leitura e escrita','Uma proposta de escrita pode pedir que estudantes produzam um texto para um público definido, considerando objetivo, gênero e informações necessárias. Depois, critérios de revisão podem abordar clareza, organização, adequação ao gênero e aspectos convencionais da escrita.

Na leitura, perguntas podem ir além da localização literal de informações e pedir comparação, inferência, explicação de relações ou avaliação de uma ideia. Assim, a prática desenvolve tanto conhecimentos sobre a língua quanto capacidades de compreender e agir por meio dela.',7,'examples'),
('10c77160-d405-4484-a63c-e29ab1342f87'::uuid,'Conexões entre fluência, compreensão e práticas sociais','A leitura envolve diferentes processos. Reconhecer palavras com maior automaticidade pode favorecer a fluência, mas compreender exige construir sentidos, relacionar informações e fazer inferências. Ao mesmo tempo, ler e escrever acontecem em práticas sociais com gêneros e finalidades específicas.

Uma sequência de ensino pode combinar trabalho explícito sobre aspectos da leitura e da escrita com situações reais de uso da linguagem. O ponto não é escolher entre técnica e significado, mas organizar aprendizagens que se apoiem mutuamente.',6,'deepening'),
('10c77160-d405-4484-a63c-e29ab1342f87'::uuid,'Checklist de domínio para prova e trabalho','Você domina este tópico quando consegue: explicar compreensão leitora; diferenciar fluência de compreensão; reconhecer a importância de gênero e finalidade; analisar uma proposta de produção escrita; e identificar oportunidades de uso social da linguagem.

Em provas, procure o processo cognitivo exigido pela pergunta. Em trabalhos, relacione a proposta de leitura ou escrita ao público, finalidade e contexto de circulação.',8,'review')
) v(material_id,title,content,position,section_type)
where not exists (
  select 1 from public.material_sections ms
  where ms.material_id=v.material_id and ms.title=v.title
);

with data as (
  select * from jsonb_to_recordset('[{"topic_id":"7b5e6723-9d87-46dd-9e2e-4e00d1ec05eb","topic_name":"Desenvolvimento e aprendizagem","title":"Prática ampliada — Desenvolvimento e aprendizagem","content":"Questões adicionais para consolidar conceitos, aplicar conhecimentos e preparar provas e trabalhos.","questions":[["desenvolvimento_aprendizagem","intermediate","Uma diferença importante entre desenvolvimento e aprendizagem é que",["desenvolvimento é apenas crescimento físico, enquanto aprendizagem é apenas memorização.","desenvolvimento envolve mudanças mais amplas ao longo do tempo, enquanto aprendizagem se refere à apropriação de conhecimentos, habilidades e modos de agir.","desenvolvimento acontece somente na escola, enquanto aprendizagem acontece apenas fora dela.","desenvolvimento e aprendizagem são termos exatamente equivalentes."],1],["piaget_assimilacao_acomodacao","intermediate","Quando um estudante interpreta uma situação nova a partir de esquemas que já possui e depois os modifica diante de um desafio, esse processo se relaciona a",["repetição mecânica.","assimilação e acomodação.","memorização literal.","condicionamento sem reorganização."],1],["mediacao_zona_desenvolvimento","advanced","Um professor oferece pistas e perguntas para que um estudante realize uma tarefa que ainda não consegue resolver sozinho. Essa situação exemplifica principalmente",["isolamento cognitivo.","repetição sem interação.","mediação e apoio ajustado às possibilidades do estudante.","substituição permanente da ação do aluno."],2],["analise_situacao_educativa","advanced","Ao analisar uma dificuldade escolar, uma leitura coerente com a Psicologia da Educação evita",["considerar apenas uma causa isolada e desconsiderar contexto, interação e história de aprendizagem.","examinar conhecimentos prévios.","observar como a tarefa foi proposta.","investigar quais apoios podem favorecer o avanço."],0]]},{"topic_id":"e005f7ca-42ce-4dc7-b404-088b64af7272","topic_name":"Didática e os processos de ensinar e aprender","title":"Prática ampliada — Didática e os processos de ensinar e aprender","content":"Questões adicionais para consolidar conceitos, aplicar conhecimentos e preparar provas e trabalhos.","questions":[["conceito_didatica","introductory","A Didática pode ser entendida como um campo que estuda principalmente",["a classificação administrativa das escolas.","os processos de ensinar e aprender, suas finalidades, condições, relações e formas de organização.","somente técnicas disciplinares.","apenas avaliações finais."],1],["intencionalidade_didatica","intermediate","Uma professora escolhe uma atividade apenas porque está em alta, sem verificar sua contribuição para a aprendizagem. O principal problema é a ausência de",["intencionalidade e coerência didática.","tecnologia digital.","trabalho em grupo.","conteúdo escolar."],0],["contexto_e_decisao_didatica","intermediate","Quando o professor considera conhecimentos prévios, contexto da turma, finalidade da aula e evidências de aprendizagem para escolher uma estratégia, ele está",["tomando uma decisão didática contextualizada.","seguindo uma receita universal.","eliminando a necessidade de planejamento.","substituindo o objetivo por uma atividade."],0],["ajuste_didatico","advanced","Muitos estudantes interpretaram um conceito de forma equivocada. Uma decisão didática adequada é",["ignorar o resultado porque o plano já foi concluído.","retomar o conceito, ajustar a explicação e oferecer nova oportunidade de aplicação.","reduzir automaticamente todos os objetivos.","considerar o erro como falta de interesse."],1]]},{"topic_id":"eaf2ef11-9ed1-4253-a8ce-0c1c7a5755b7","topic_name":"Alfabetização e letramento","title":"Prática ampliada — Alfabetização e letramento","content":"Questões adicionais para consolidar conceitos, aplicar conhecimentos e preparar provas e trabalhos.","questions":[["alfabetizacao_letramento","intermediate","Alfabetização e letramento se relacionam porque",["são exatamente a mesma coisa.","a aprendizagem do sistema de escrita e a participação em práticas sociais de leitura e escrita podem ser trabalhadas de forma articulada.","letramento substitui o ensino do sistema de escrita.","alfabetização deve ocorrer somente depois do letramento."],1],["finalidade_social_texto","introductory","Discutir para que serve um cartaz antes de analisar sua escrita contribui principalmente para",["compreender a finalidade e o contexto social do texto.","evitar reflexão sobre a escrita.","substituir leitura por conversa.","ensinar apenas regras ortográficas."],0],["integracao_pratica","advanced","Uma professora combina leitura compartilhada, conversa sobre a finalidade do texto e reflexão sobre palavras e letras. Essa proposta",["integra práticas de uso da linguagem e conhecimentos sobre o sistema de escrita.","impede a sistematização do código.","faz o sistema deixar de ser ensinado.","transforma toda atividade em avaliação."],0],["avaliacao_alfabetizacao_letramento","advanced","Ao avaliar uma turma de alfabetização, é mais informativo observar",["somente velocidade de cópia.","somente memorização do alfabeto.","tanto conhecimentos sobre o sistema de escrita quanto participação e produção de sentidos em práticas de leitura e escrita.","somente a quantidade de páginas preenchidas."],2]]},{"topic_id":"d88141bb-0724-4f63-b9d5-466c34dde2cf","topic_name":"Planejamento do ensino","title":"Prática ampliada — Planejamento do ensino","content":"Questões adicionais para consolidar conceitos, aplicar conhecimentos e preparar provas e trabalhos.","questions":[["objetivos_planejamento","intermediate","Um planejamento de ensino coerente começa por",["escolher primeiro a atividade mais divertida.","clarear o que se espera que os estudantes aprendam e usar isso para orientar conteúdos, estratégias e avaliação.","definir somente a quantidade de páginas.","escolher a prova antes dos objetivos."],1],["alinhamento_objetivo_avaliacao","advanced","Um professor define como objetivo que os estudantes comparem duas concepções, mas avalia apenas se memorizaram uma definição. O problema principal é",["falta de alinhamento entre objetivo e avaliação.","excesso de conteúdo.","ausência de tecnologia.","falta de trabalho em grupo."],0],["replanejamento","intermediate","Evidências mostram que a turma ainda não compreendeu um conceito essencial. Replanejar significa",["abandonar imediatamente o objetivo.","rever decisões de ensino para criar melhores condições de aprendizagem, preservando a finalidade.","recomeçar todo o semestre.","substituir avaliação por presença."],1],["flexibilidade_planejamento","advanced","Qual situação mostra melhor um planejamento flexível?",["mudar de objetivo a cada erro.","manter objetivos centrais e alterar estratégias, exemplos ou ritmo com base nas evidências de aprendizagem.","abandonar o planejamento diante de qualquer dificuldade.","seguir exatamente o roteiro mesmo quando as evidências contradizem as expectativas."],1]]},{"topic_id":"7b8f766f-dc23-44ce-8b44-7fc5c0135ddd","topic_name":"Construtivismo e construção do conhecimento","title":"Prática ampliada — Construtivismo e construção do conhecimento","content":"Questões adicionais para consolidar conceitos, aplicar conhecimentos e preparar provas e trabalhos.","questions":[["construcao_conhecimento","introductory","Na perspectiva construtivista, o conhecimento é compreendido como",["uma cópia passiva da realidade.","algo que o sujeito constrói e reorganiza em sua interação com objetos de conhecimento e situações.","um conjunto de respostas que nunca se modifica.","informação transmitida pronta."],1],["desequilibrio_reorganizacao","intermediate","Quando um estudante encontra uma situação que não se encaixa em seus esquemas e precisa reorganizá-los, isso se relaciona a",["desequilíbrio e reconstrução.","repetição sem mudança.","memorização literal.","controle disciplinar."],0],["mito_construtivismo","advanced","Uma interpretação inadequada do construtivismo seria dizer que",["o aluno deve descobrir tudo sozinho e o professor não precisa ensinar ou intervir.","o estudante participa ativamente da construção do conhecimento.","as ideias prévias importam.","situações-problema podem favorecer reorganizações."],0],["papel_professor","advanced","Em uma proposta construtivista, o papel do professor é melhor descrito como",["deixar a turma sem orientação.","organizar situações, intervenções e perguntas que favoreçam a aprendizagem, acompanhando os raciocínios.","dar respostas antes de qualquer tentativa.","corrigir apenas o resultado final."],1]]},{"topic_id":"2faefa1c-5ece-4741-839e-6c5e0d936db7","topic_name":"Sistema de escrita alfabética","title":"Prática ampliada — Sistema de escrita alfabética","content":"Questões adicionais para consolidar conceitos, aplicar conhecimentos e preparar provas e trabalhos.","questions":[["principio_alfabetico","introductory","O princípio alfabético diz respeito à compreensão de que",["cada letra representa sempre uma palavra inteira.","há relações sistemáticas entre unidades sonoras da fala e unidades gráficas da escrita alfabética.","escrever significa apenas copiar modelos.","a ortografia não possui regularidades."],1],["grafema_fonema","intermediate","Grafema e fonema não são sinônimos porque",["grafema é uma unidade gráfica, enquanto fonema é uma unidade sonora.","ambos são nomes diferentes para a mesma letra.","fonema é sempre uma palavra.","grafema existe apenas na fala."],0],["ensino_explicito","intermediate","Ensinar relações entre sons e letras de forma explícita pode ajudar o estudante a",["memorizar textos sem análise.","compreender padrões e ampliar sua capacidade de ler e escrever novas palavras.","evitar reflexão sobre a escrita.","substituir leitura por cópia."],1],["diagnostico_escrita","advanced","Ao analisar uma escrita infantil não convencional, uma atitude pedagogicamente mais informativa é",["corrigir o resultado e encerrar.","investigar o que o estudante já compreende sobre o sistema para planejar intervenções adequadas.","considerar o erro como falta de atenção sem análise.","substituir a escrita por desenho."],1]]},{"topic_id":"f7446705-aa47-4426-9832-35a72753f161","topic_name":"Consciência fonológica e relações grafofonêmicas","title":"Prática ampliada — Consciência fonológica e relações grafofonêmicas","content":"Questões adicionais para consolidar conceitos, aplicar conhecimentos e preparar provas e trabalhos.","questions":[["rima","introductory","Uma atividade que pede para encontrar palavras que rimam trabalha principalmente",["atenção às semelhanças sonoras em unidades maiores da palavra, como a rima.","somente reconhecimento visual de letras.","caligrafia.","compreensão textual profunda."],0],["rima_exemplo","introductory","Qual par apresenta uma relação de rima mais adequada?",["casa / cama","casa / asa","mesa / medo","bola / barco"],1],["consciencia_fonemica","intermediate","Quando o estudante identifica que /m/ e /p/ são unidades sonoras diferentes, ele está mobilizando principalmente",["consciência fonêmica.","conhecimento de gênero textual.","fluência de leitura.","produção escrita."],0],["relacao_grafofonemica","advanced","A relação grafofonêmica diz respeito à articulação entre",["unidades gráficas da escrita e unidades sonoras da fala, considerando as convenções do sistema.","parágrafos e capítulos.","ilustrações e títulos.","somente significado e contexto."],0]]},{"topic_id":"60592ad9-932f-41cb-afba-1b022b8cdecb","topic_name":"Psicologia histórico-cultural e mediação","title":"Prática ampliada — Psicologia histórico-cultural e mediação","content":"Questões adicionais para consolidar conceitos, aplicar conhecimentos e preparar provas e trabalhos.","questions":[["historico_cultural","introductory","Na perspectiva histórico-cultural, o desenvolvimento humano é compreendido considerando fortemente",["apenas maturação biológica.","as relações sociais, a cultura e a história em que o sujeito participa.","somente características fixas.","apenas desempenho em testes."],1],["mediacao","intermediate","Mediação ajuda a compreender que",["a relação do sujeito com o mundo é organizada por instrumentos, signos, linguagem e outras formas culturalmente construídas.","o aluno aprende sem relações sociais.","o professor apenas transmite respostas.","o desenvolvimento ocorre separado da cultura."],0],["linguagem_mediacao","intermediate","Quando a linguagem orienta o pensamento e a ação em uma atividade conjunta, ela pode atuar como",["instrumento de mediação do desenvolvimento e da aprendizagem.","elemento sem função educativa.","mera decoração da aula.","substituto do pensamento."],0],["papel_escola","advanced","A escola possui papel relevante nessa perspectiva porque",["pode organizar experiências e conhecimentos culturais que ampliam as possibilidades de desenvolvimento.","deve evitar conhecimentos sistematizados.","atua apenas como espaço informal.","não interfere nas oportunidades de aprendizagem."],0]]},{"topic_id":"aab5c0f7-fb5c-41f1-a0ae-96a0ae4f99c3","topic_name":"Objetivos, conteúdos e métodos de ensino","title":"Prática ampliada — Objetivos, conteúdos e métodos de ensino","content":"Questões adicionais para consolidar conceitos, aplicar conhecimentos e preparar provas e trabalhos.","questions":[["objetivos_aprendizagem","introductory","Um bom objetivo de aprendizagem descreve principalmente",["o que o professor fará em aula.","o que se espera que o estudante seja capaz de fazer, compreender ou demonstrar.","a quantidade de páginas.","o recurso tecnológico."],1],["objetivo_observavel","intermediate","Qual formulação é mais observável?",["Estudar o capítulo.","Compreender profundamente a educação.","Comparar duas concepções de avaliação usando critérios definidos.","Assistir à aula."],2],["selecao_conteudos","intermediate","A seleção de conteúdos deve estar relacionada",["aos objetivos de aprendizagem, à relevância do conhecimento e às condições concretas de ensino.","somente ao interesse do professor.","à quantidade de materiais.","à ferramenta digital escolhida."],0],["alinhamento_metodo_objetivo","advanced","Um método de ensino é mais coerente quando",["é o mais popular.","favorece as operações cognitivas e aprendizagens previstas nos objetivos.","é sempre o mais tecnológico.","é usado pelo maior número de professores."],1]]},{"topic_id":"33c08f0b-9c61-42d2-9bd1-9cbb343dcca0","topic_name":"Avaliação da aprendizagem","title":"Prática ampliada — Avaliação da aprendizagem","content":"Questões adicionais para consolidar conceitos, aplicar conhecimentos e preparar provas e trabalhos.","questions":[["avaliacao_diagnostica","introductory","A função diagnóstica da avaliação está principalmente relacionada a",["atribuir uma nota final.","identificar conhecimentos, necessidades e condições iniciais que ajudam a orientar o ensino.","classificar definitivamente.","encerrar o ensino."],1],["avaliacao_formativa","intermediate","A avaliação formativa se caracteriza por",["produzir evidências durante o processo e usá-las para orientar feedback e decisões.","ocorrer somente no final do semestre.","servir apenas para classificação.","dispensar critérios."],0],["criterios_avaliacao","intermediate","Critérios claros são importantes porque",["eliminam toda subjetividade.","ajudam a tornar explícito o que será considerado evidência de qualidade na produção do estudante.","substituem o ensino.","fazem a nota ser automaticamente alta."],1],["feedback_avaliacao","advanced","Um feedback educativo é mais útil quando",["apenas diz certo ou errado.","indica o que já foi alcançado, o que precisa ser melhorado e como o estudante pode avançar.","compara o aluno com o colega.","apresenta somente a nota."],1]]},{"topic_id":"b95907ea-b1bf-44f9-8a63-744dc9584248","topic_name":"Interação, afetividade e práticas educativas","title":"Prática ampliada — Interação, afetividade e práticas educativas","content":"Questões adicionais para consolidar conceitos, aplicar conhecimentos e preparar provas e trabalhos.","questions":[["afetividade_educacao","intermediate","Reconhecer a dimensão afetiva da relação educativa significa compreender que",["emoções, vínculos, expectativas e relações influenciam as condições em que o estudante aprende.","o professor deve evitar qualquer limite.","conteúdo acadêmico não é necessário.","toda avaliação deve ser informal."],0],["interacao_professor_aluno","intermediate","Uma interação professor-aluno favorece a aprendizagem quando",["combina respeito, clareza de expectativas, escuta e intervenções pedagógicas intencionais.","elimina qualquer cobrança.","evita feedbacks difíceis.","substitui objetivos por acolhimento."],0],["afetividade_cognicao","introductory","A relação entre afetividade e cognição é melhor descrita como",["dimensões que se articulam na experiência educativa, e não como elementos necessariamente concorrentes.","duas dimensões incompatíveis.","afetividade sempre substitui raciocínio.","cognição só acontece sem emoção."],0],["acolhimento_exigencia","advanced","Um professor oferece apoio diante de um erro, mas mantém o critério de aprendizagem e ajuda o estudante a revisar o raciocínio. Essa postura indica que",["acolhimento e exigência pedagógica podem coexistir.","afetividade exige diminuir o objetivo.","o erro deve ser ignorado.","o professor precisa resolver tudo pelo estudante."],0]]},{"topic_id":"b8e922a1-c4a4-48fc-9691-e4361cc9118a","topic_name":"Leitura, escrita e práticas sociais","title":"Prática ampliada — Leitura, escrita e práticas sociais","content":"Questões adicionais para consolidar conceitos, aplicar conhecimentos e preparar provas e trabalhos.","questions":[["compreensao_leitora","intermediate","Compreender um texto envolve mais do que reconhecer palavras porque",["o leitor também constrói sentidos, relaciona informações, faz inferências e considera conhecimentos prévios e contexto.","decodificação não tem importância.","somente memorização importa.","o leitor deve evitar inferências."],0],["inferencia","introductory","Perguntar por que um personagem tomou uma decisão favorece principalmente",["a construção de inferências e a compreensão das relações presentes no texto.","apenas a cópia de frases.","somente a velocidade de leitura.","apenas o reconhecimento de letras."],0],["genero_finalidade","intermediate","Considerar o gênero e a finalidade de um texto é importante porque",["todos os textos devem ser lidos do mesmo modo.","as práticas de leitura e escrita acontecem em situações sociais com objetivos comunicativos diferentes.","gêneros não influenciam compreensão.","finalidade importa apenas para textos literários."],1],["fluencia_compreensao","advanced","Fluência de leitura e compreensão são relacionadas, mas não equivalentes porque",["um leitor pode ler com maior automaticidade e ainda ter dificuldades para construir o sentido do texto.","fluência garante compreensão em qualquer situação.","compreensão elimina a necessidade de fluência.","as duas habilidades são exatamente a mesma coisa."],0]]}]'::jsonb)
    as d(topic_id uuid,topic_name text,title text,content text,questions jsonb)
),
new_exercises as (
  insert into public.exercises(topic_id,title,exercise_type,content,difficulty,position,published)
  select d.topic_id,d.title,'application',d.content,'medium',7,true
  from data d
  where not exists (
    select 1 from public.exercises e
    where e.topic_id=d.topic_id and e.exercise_type='application' and e.title=d.title
  )
  returning id,topic_id
),
target_exercises as (
  select id,topic_id from new_exercises
  union all
  select e.id,e.topic_id
  from public.exercises e
  join data d on d.topic_id=e.topic_id and d.title=e.title
  where e.exercise_type='application'
),
question_source as (
  select te.id exercise_id,
         q.ord::int position,
         q.value->>'text' question_text,
         q.value->>'tag' tag,
         q.value->>'difficulty' difficulty,
         (q.value->>'correct')::int correct_index,
         q.value->'options' options
  from target_exercises te
  join data d on d.topic_id=te.topic_id
  cross join lateral jsonb_array_elements(
    d.questions
  ) with ordinality q(value,ord)
),
inserted_questions as (
  insert into public.exercise_questions
    (exercise_id,question_text,question_type,position,feedback_hint,difficulty_tag)
  select qs.exercise_id,qs.question_text,'multiple_choice',
         (select coalesce(max(eq.position),0)+qs.position
          from public.exercise_questions eq
          where eq.exercise_id=qs.exercise_id),
         'Compare a alternativa escolhida com o conceito central e com a situação apresentada.',
         array[qs.tag]
  from question_source qs
  where not exists (
    select 1 from public.exercise_questions eq
    where eq.exercise_id=qs.exercise_id and eq.question_text=qs.question_text
  )
  returning id,exercise_id,question_text
)
insert into public.exercise_options
  (question_id,content,is_correct,feedback_correct,feedback_incorrect,position)
select iq.id,
       qs.options->>idx,
       idx=qs.correct_index,
       case when idx=qs.correct_index then
         'Correto. A alternativa está de acordo com o conceito estudado.'
       else null end,
       case when idx<>qs.correct_index then
         'Releia o conceito central e compare-o com a situação apresentada.'
       else null end,
       idx+1
from inserted_questions iq
join question_source qs
  on qs.exercise_id=iq.exercise_id and qs.question_text=iq.question_text
cross join lateral generate_series(0,3) idx;

commit;
